import{_ as t,l as o,o as a,c as s,v as i,p as n,x as r,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"能耗感知调度 EAS","description":"","frontmatter":{"title":"能耗感知调度 EAS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/eas-scheduling.md","filePath":"cs/eas-scheduling.md","lastUpdated":1789023840000}'),p={name:"cs/eas-scheduling.md"};function h(u,e,A,_,m,S){const l=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=i('<h1 id="能耗感知调度-eas" tabindex="-1">能耗感知调度 EAS <a class="header-anchor" href="#能耗感知调度-eas" aria-label="Permalink to &quot;能耗感知调度 EAS&quot;">​</a></h1><div class="epigraph"><p>EAS 用能量模型估计「在哪颗核、哪个频率跑这个任务更省」，在满足容量的前提下偏向高效核。</p><footer>—— 据 Linux Energy Aware Scheduling 文档；ARM 对 EM 能量模型的说明</footer></div><p><a href="/cs/sched-domains">调度域</a> 只看负载与缓存。手机与服务器都要 <strong>焦耳</strong>。缺口是 EAS：把 <a href="/cs/cpufreq-governor">cpufreq</a> 的频率与容量接入选核。异构核细节下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同样负载，小核低频可能更省，大核更快。能量模型：每 CPU 一组（频率，功耗，容量）。wakeup：在域里找能消化 util 且能量增量最小的 CPU。缺口：util 估计（PELT）误差；关 EAS 则退回只看 idle。本课不把 Android 的全部 vendor 补丁当主线。</p><p><span class="marginnote">EM 来自 DT/firmware。没有模型则 EAS 不启用。对象是选核，不是编译器优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任务 util 更新 → wake → <code>find_energy_efficient_cpu</code> 扫候选。对照 BFQ：一个省磁盘延迟公平，一个省电。对照 <a href="/cs/io-polling">NAPI poll</a>：poll 核不进 C-state，EAS 算出来也会「贵」。</p>',8)),(a(),n(c,null,{default:r(()=>[E(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UTIL%5B%22%E4%BB%BB%E5%8A%A1%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%20--%3E%20EM%5B%22%E8%83%BD%E9%87%8F%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20EM%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%20CPU%22%5D%0A%20%20CAND%20--%3E%20MIN%5B%22%E8%83%BD%E9%87%8F%E5%A2%9E%E9%87%8F%E6%9C%80%E5%B0%8F%E4%B8%94%E5%AE%B9%E9%87%8F%E5%A4%9F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EAS 把功耗变成调度输入，使「永远大核」不再是默认。它依赖模型诚实与 util 稳定。不要写成气候课。与 memcg：内存不够会睡，util 下降，选核跟着变。</p><p>过激节能会伤尾延迟，故有容量余量。</p><p>实现上：没有 energy model 时 EAS 直接关闭。util 估计滞后会把任务放错核，表现为掉帧。EAS 与 schedutil 共用 PELT，改一边会影响另一边。 读法上只引用<a href="/cs/sched-domains">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>能耗感知调度 EAS</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每个 governor 与 EAS 的交互矩阵——governor 后课。下一课把大小核拓扑钉死：异构调度。</p><p>版本字段会变，课序钉的是机制对象「能耗感知调度 EAS」，不是某一主线内核的结构体名。 后课默认：选核可最小化能量增量。大核小核如何分任务，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EAS 用能量模型在容量约束下选核。</li><li>依赖 PELT 与固件 EM。</li><li>异构核调度是下一课。</li><li>出处：Linux EAS；ARM energy model。</li></ul>',11))])}const T=t(p,[["render",h]]);export{g as __pageData,T as default};
